export const SCHEMA_REFERENCE: string = "// ===== core.ts =====\n// Shared value types (docs/05 \"Shared value types\"). These are the primitives that flow\n// across every seam: Store rows, Ctx reads/writes, Host marshalling, view bindings.\n\n/** ULID string. */\nexport type Id = string;\n\n/**\n * A JSON-ish serializable value. This is the closed set of things that can cross the\n * isolate boundary (marshalled in/out of QuickJS) and be persisted. `Date` is included\n * because the runtime hydrates datetime fields to `Date` before app logic sees them.\n */\nexport type Value =\n  | string\n  | number\n  | boolean\n  | Date\n  | null\n  | Value[]\n  | { [k: string]: Value };\n\n/**\n * A raw stored record as the Store returns it: identity + timestamps + opaque field data.\n * Fields are `unknown` here because at the storage seam nothing has been resolved or\n * narrowed yet — the runtime is responsible for hydration/resolution.\n *\n * Named `PotyroRecord` (not `Record`) to avoid clashing with the TS built-in `Record<K,V>`.\n */\nexport interface PotyroRecord {\n  id: Id;\n  createdAt: string;\n  updatedAt: string;\n  /**\n   * Who entered this record — the account id of whoever inserted it (KA-18).\n   *\n   * **Stamped by the host and never app-settable.** In a shared ledger, code that could write its\n   * own `createdBy` could rewrite authorship, and untrusted code is exactly the code that would\n   * want to. An app that wants an editable \"who did this\" uses an ordinary `member` field: who\n   * *entered* an expense is genuinely not who *paid* for it (spike F5), and conflating the two\n   * makes the unforgeable one useless.\n   *\n   * Optional because records written before this existed do not have it, and because a `Store` is\n   * free of identity — the runtime stamps it.\n   */\n  createdBy?: Id;\n  [field: string]: unknown;\n}\n\n/**\n * The app-facing record handed to logic functions (`computed`/`action`/`filter`/`sort`/\n * `binding`/`reminder`). Relations are resolved one level deep and computed values are\n * accessible as properties.\n *\n * It is deliberately permissive (`any` member access). This is the \"no ceiling\" record from\n * docs/04: app logic is unrestricted TypeScript, so field/relation/computed access is not\n * statically constrained here. Static shape safety lives in the declarative field\n * definitions + Zod validation, *not* in this record type — that is the whole point of the\n * \"structure is declarative and validated; logic is typed, not validated\" split (CLAUDE.md).\n */\nexport type Resolved = {\n  id: Id;\n  createdAt: string;\n  updatedAt: string;\n  // The escape hatch: any field/relation/computed is reachable. Intentional, see above.\n  // eslint-disable-next-line @typescript-eslint/no-explicit-any\n  [field: string]: any;\n};\n\n/** A `file` field's value. Build it from a `FileInfo`: `{ id, path, name, mime }`. */\nexport interface FileRef {\n  id: string;\n  path?: string;\n  name?: string;\n  mime?: string;\n}\n\n/** Reference to a stored blob (media field value). */\nexport interface MediaRef {\n  key: string;\n  mime: string;\n  w?: number;\n  h?: number;\n}\n\n/** A geographic point (geo field value). */\nexport interface Geo {\n  lat: number;\n  lng: number;\n  label?: string;\n}\n\n// ===== words.ts =====\n// Words an app shows to a person, in one language or several (#302, docs/20).\n\n/** A BCP 47 language tag: \"en\", \"pl\", \"pt-BR\", \"de-CH\". */\nexport type Language = string;\n\n/**\n * Words a person reads, in the app's own language; their translations are the app's catalogs,\n * `locales/<lang>.po` (docs/30). Where one text means two things (\"Water\" the verb and the noun),\n * `{ text, context }` tells them apart. A per-language map `{ en, pl }` is the older form (docs/20),\n * still read. Records are never translated.\n */\nexport type Words = string | ContextWords | WordsMap;\n\n/** Words with a `context`: the same text, translated apart (gettext's `msgctxt`). */\nexport type ContextWords = { readonly text: string; readonly context: string };\n\n/** The per-language form of `Words`. */\nexport type WordsMap = { readonly [language: Language]: string };\n\n// ===== fields.ts =====\n// Field types — the declarative, closed set (docs/03 \"Field types\").\n//\n// `text · richtext · number · boolean · enum · tags · datetime · duration · url · geo ·\n//  media · relation · list`. There is intentionally no `computed` field *type* — computed is\n// a function block on the entity, which cleanly separates shape (data) from logic (code).\n\n/** `default` may be a literal value or a function of `ctx` (docs/03). */\nexport type DefaultValue = unknown | ((ctx: Ctx) => unknown);\n\n/** Common options shared by every field variant. */\nexport interface FieldCommon {\n  label?: Words;\n  required?: boolean;\n  hidden?: boolean;\n  /** One line under the control on the form: what to put here, or why it matters (#100). */\n  help?: Words;\n  /** Example text in the empty control (text, url, number). */\n  placeholder?: Words;\n  /** `\"half\"` lets two short neighbours share a row on a wide form; they stack on a phone. */\n  width?: \"full\" | \"half\";\n  /** Literal default, or `(ctx) => value`. Not validated (may be a function). */\n  default?: DefaultValue;\n}\n\nexport interface TextField extends FieldCommon {\n  type: \"text\";\n  multiline?: boolean;\n  /** Typed into by several people at once; edited with `ctx.text`. */\n  collaborative?: boolean;\n}\n\nexport interface RichTextField extends FieldCommon {\n  type: \"richtext\";\n}\n\nexport interface NumberField extends FieldCommon {\n  type: \"number\";\n  min?: number;\n  max?: number;\n  step?: number;\n  unit?: Words;\n  integer?: boolean;\n}\n\nexport interface BooleanField extends FieldCommon {\n  type: \"boolean\";\n}\n\n/** Money as WHOLE MINOR UNITS — `4200` is €42.00 (KA-26). Never a float; `currency` is ISO 4217 and\n *  sets the minor digits (a yen has none, so `5` is ¥5). Why, and how to split: docs/03. */\nexport interface MoneyField extends FieldCommon {\n  type: \"money\";\n  /** ISO 4217. Defaults to EUR when the app does not say. */\n  currency?: string;\n  min?: number;\n  max?: number;\n}\n\n/** The colours an enum value may be given. A closed set, so a shared app cannot walk off the\n *  palette or land unreadable text on its own background (#98). */\nexport const ENUM_COLORS = [\"red\", \"orange\", \"yellow\", \"green\", \"teal\", \"blue\", \"purple\", \"pink\", \"grey\"] as const;\nexport type EnumColor = (typeof ENUM_COLORS)[number];\n\nexport interface EnumField extends FieldCommon {\n  type: \"enum\";\n  options: string[];\n  /** Colour per option, for values that mean something — `{ overdue: \"red\", done: \"green\" }`.\n   *  Options left out keep the colour derived from their name, which is stable everywhere. */\n  colors?: Record<string, EnumColor>;\n  /** What each option reads as: `{ todo: { en: \"To do\", pl: \"Do zrobienia\" } }`. Records keep the option. */\n  labels?: Record<string, Words>;\n  /** Overrides the control the option count would choose: up to five options are a row of\n   *  buttons, more open a searchable picker. */\n  control?: \"segmented\" | \"picker\";\n}\n\nexport interface TagsField extends FieldCommon {\n  type: \"tags\";\n  options?: string[];\n  /** As for an enum. */\n  labels?: Record<string, Words>;\n}\n\nexport interface DateTimeField extends FieldCommon {\n  type: \"datetime\";\n  /** `\"day\"` (the default): a date, no time — the picker offers days and the value reads as one.\n   *  `\"minute\"`: the field keeps the time too (a session start, an appointment). Most fields want\n   *  the day; ask for the minute only when the hour matters (#103). */\n  precision?: \"day\" | \"minute\";\n}\n\nexport interface DurationField extends FieldCommon {\n  type: \"duration\";\n  /** Base unit the stored number represents. */\n  unit?: \"ms\" | \"s\" | \"min\" | \"h\" | \"d\";\n}\n\nexport interface UrlField extends FieldCommon {\n  type: \"url\";\n}\n\nexport interface GeoField extends FieldCommon {\n  type: \"geo\";\n}\n\n/** A file in the app's own folder; the value is a `FileRef`. `accept` like `\".md,.txt\"`. */\nexport interface FileField extends FieldCommon {\n  type: \"file\";\n  accept?: string;\n  /** where imported files land */\n  folder?: string;\n}\n\nexport interface MediaField extends FieldCommon {\n  type: \"media\";\n  accept?: \"image\" | \"video\" | \"audio\" | \"any\";\n  multiple?: boolean;\n  /**\n   * Keep a photo exactly as the camera took it. Off by default: a phone camera makes a 4000-pixel,\n   * four-megabyte JPEG, and an app holding a few dozen of those fills the device — and, in a shared\n   * app, pushes every one of those megabytes to every person in it. Photos are stored at 2048\n   * pixels on their longest edge instead, which is more than a screen shows and still prints small.\n   *\n   * Turn it on where the pixels ARE the point: a scanned document, a receipt to be read back later,\n   * a photo meant to be cropped hard. Re-encoding also drops the file's EXIF data.\n   */\n  full?: boolean;\n}\n\nexport interface RelationField extends FieldCommon {\n  type: \"relation\";\n  /** Target entity key. */\n  to: string;\n  many?: boolean;\n}\n\n/**\n * A person in this app's space (KA-19) — assignee, owner, borrower, participant.\n *\n * Deliberately NOT a `relation` to a `person` entity. Membership lives in space metadata,\n * maintained by the invite and key machinery, not in rows the app can write; modelling it as a\n * relation would let any app forge a member, and would give every shared app the chore of keeping\n * a people table in step with who is actually in the space. As a distinct type the runtime can\n * render a real person chip and validate values against `ctx.space.members`.\n *\n * Stored as an account id (or an array of them with `many`). Resolves to a `Person`, so\n * `e.paidBy.name` works. Solo degrades to the single local identity rather than to nothing.\n */\nexport interface MemberField extends FieldCommon {\n  type: \"member\";\n  many?: boolean;\n}\n\n/** A list of homogeneous nested rows. Each row is a mini field set (`of`). */\nexport interface ListField extends FieldCommon {\n  type: \"list\";\n  of: Record<string, Field>;\n  ordered?: boolean;\n  /** Rows as lines of these parts: \"350 g flour\". */\n  lines?: string[];\n}\n\n/** The discriminated union of all field variants. */\nexport type Field =\n  | TextField\n  | RichTextField\n  | NumberField\n  | BooleanField\n  | MoneyField\n  | EnumField\n  | TagsField\n  | DateTimeField\n  | DurationField\n  | UrlField\n  | GeoField\n  | MediaField\n  | FileField\n  | RelationField\n  | MemberField\n  | ListField;\n\n/** All valid field type discriminants. */\nexport const FIELD_TYPES = [\n  \"text\",\n  \"richtext\",\n  \"number\",\n  \"boolean\",\n  \"money\",\n  \"enum\",\n  \"tags\",\n  \"datetime\",\n  \"duration\",\n  \"url\",\n  \"geo\",\n  \"media\",\n  \"file\",\n  \"relation\",\n  \"member\",\n  \"list\",\n] as const;\n\nexport type FieldType = (typeof FIELD_TYPES)[number];\n\n// ===== ctx.ts =====\n// `ctx` — the host API surface (docs/04). This is *the* contract: every host power reaches\n// app code only through `ctx`. Growing the system means growing this interface, never adding\n// language features to a DSL (there is no DSL).\n//\n// `ctx` is constructed by the host (WP2). Its data/time/storage/ui/nav members are always\n// present; its `caps` members are real+unmediated for trusted apps and mediated (or absent)\n// for untrusted apps. App code sees the same interface either way — authority is what differs.\n\n/** Query spec for `ctx.query` — JS predicates run in-memory over resolved rows. */\nexport interface QuerySpec {\n  filter?: (r: Resolved) => boolean;\n  sort?: (a: Resolved, b: Resolved) => number;\n  limit?: number;\n  offset?: number;\n}\n\n/**\n * A person — you, or someone you share a space with (KA-18, ADR D2 amended).\n *\n * `id` is a cojson account id, stable for life. It is the *provable* identity: cojson signs every\n * transaction with the account that made it, which is what lets `createdBy` mean something in a\n * shared ledger. An id an app could write into a field would be forgeable by any member.\n */\nexport interface Person {\n  id: Id;\n  name: string;\n  guest?: true; // not joined yet: see ctx.guests\n}\n\n/** App-scoped key/value storage, separate from entity records. */\nexport interface CtxStorage {\n  get<T = unknown>(k: string): Promise<T | null>;\n  set(k: string, v: unknown): Promise<void>;\n  delete(k: string): Promise<void>;\n  keys(prefix?: string): Promise<string[]>;\n}\n\n/** UI affordances provided by the shell (docs/04). */\n/** Takes `Words` wherever it takes words. */\nexport interface CtxUi {\n  toast(msg: Words): void;\n  /**\n   * `ok` names the button (\"Delete\"); `destructive` makes it red; `detail` is a quieter second line.\n   *\n   * `cancel` names the other button — worth naming whenever both answers are real choices (\"Delete\n   * them\" / \"Move them up\") rather than an action and a way out of it.\n   */\n  confirm(msg: Words, opts?: { detail?: Words; ok?: Words; cancel?: Words; destructive?: boolean }): Promise<boolean>;\n  prompt(msg: Words, opts?: { default?: string }): Promise<string | null>;\n  pick<T>(items: T[], opts?: { label?: (t: T) => string; multi?: boolean }): Promise<T | T[] | null>;\n}\n\n/**\n * The complete host API surface handed to app functions. See docs/04 for the design rules:\n * members are stable, minimal, composable, async-by-default for anything touching\n * storage/caps, and `now()` is fixed per evaluation pass for deterministic computed values.\n */\nexport interface Ctx {\n  // ---- data (all reads return Resolved records) ----\n  query(entity: string, spec?: QuerySpec): Promise<Resolved[]>;\n  get(entity: string, id: Id): Promise<Resolved | null>;\n  create(entity: string, data: Record<string, unknown>): Promise<Resolved>;\n  patch(entity: string, id: Id, data: Record<string, unknown>): Promise<Resolved>;\n  /**\n   * Add to a number — use this instead of `patch` for anything people count.\n   *\n   * `patch(id, { n: record.n + 1 })` from two people at once loses a press: both read 0, both write\n   * 1. Stating the CHANGE lets the store add them up. `record.n` is still one number.\n   */\n  increment(entity: string, id: Id, field: string, delta: number): Promise<Resolved>;\n  delete(entity: string, id: Id): Promise<void>;\n  transaction<T>(fn: (tx: Ctx) => Promise<T>): Promise<T>;\n\n  // ---- time (injected once per evaluation pass for determinism) ----\n  now(): Date;\n  today(): Date;\n\n  // ---- identity (KA-18) ----\n  /**\n   * Who you are. **Always present**, including in a solo app that has never synced — so app code\n   * never has to branch on whether identity or sync exists.\n   */\n  me: Person;\n  /**\n   * The space this app's data lives in, or `undefined` for a solo (local-only) app.\n   *\n   * Solo is a space with one member and no transport, so the honest reading of \"everyone here\" is\n   * `ctx.space?.members ?? [ctx.me]`.\n   */\n  space?: Space;\n\n  /**\n   * Runtime inputs: the values of the current page's filter chips (`FilterChip.param`) and the\n   * route params it was navigated to with (`navigate(pageId, params)` / `onOpen.param`).\n   *\n   * Scoped PER PAGE. A chip chosen on one page is not visible to another page's `filter`, so a\n   * selection that should follow the user across pages cannot live here. (`ctx.storage` persists\n   * across pages but is async, so a synchronous `filter` cannot read it either.)\n   */\n  params: Readonly<Record<string, unknown>>;\n\n  // ---- the app's words and the person's formats (#302) ----\n  /** The language the app's words are shown in: one of its `languages`. Fixed per pass. */\n  locale: Language;\n  /** Words for `ctx.locale`. With `vars`, an ICU message: `ctx.t({ en: \"{n, plural, one {# plant} other {# plants}}\", pl: \"…\" }, { n })`. */\n  t(words: Words, vars?: Record<string, string | number | Date>): string;\n  format: CtxFormat;\n\n  // ---- app-scoped key/value storage ----\n  storage: CtxStorage;\n\n  // ---- native capabilities (may be denied/scoped for untrusted apps) ----\n  caps: Caps;\n\n  // ---- media helpers ----\n  media: CtxMedia;\n\n  // ---- the app's own folder (#252) ----\n  files: CtxFiles;\n\n  // ---- UI affordances provided by the shell ----\n  ui: CtxUi;\n\n  // ---- the views that are on screen (what `camera` cannot do, because it is read only at open) ----\n  views: CtxViews;\n\n  // ---- navigation (in view/action contexts) ----\n  navigate(pageId: string, params?: Record<string, string>): void;\n\n  // ---- diagnostics ----\n  log(...args: unknown[]): void;\n}\n\n/** Re-export so consumers can name the value type without reaching into core. */\nexport type { Value, Geo };\n\n// ===== app.ts =====\n// The `AppDefinition` shape: declarative structure (data) + co-located logic (functions).\n// docs/03 is the source of truth for this file.\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Logic function signatures (docs/04). The record param is `Resolved` — the permissive\n// \"no ceiling\" record. Logic is typed by TS but not statically constrained by field shape;\n// that is by design (see core.ts `Resolved`).\n// ─────────────────────────────────────────────────────────────────────────────\n\nexport type Computed = (record: Resolved, ctx: Ctx) => Value | Promise<Value>;\nexport type ActionFn = (record: Resolved, ctx: Ctx, input?: unknown) => void | Promise<void>;\nexport type FilterFn = (record: Resolved, ctx: Ctx) => boolean;\n/** Orders two rows. `ctx` (#133) lets a sort read the selection, the page's chips or the user's\n *  position: `(a, b, ctx) => distance(a, ctx.params.me) - distance(b, ctx.params.me)`. */\nexport type SortFn = (a: Resolved, b: Resolved, ctx: Ctx) => number;\nexport type BindingFn<T = Value> = (record: Resolved, ctx: Ctx) => T;\nexport type ReminderWhen = (record: Resolved, ctx: Ctx) => Date | null;\n\n/** A view binding is either a field-key string or a function computing the value. */\nexport type Binding<T = Value> = string | BindingFn<T>;\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Entities\n// ─────────────────────────────────────────────────────────────────────────────\n\n/** A titled run of fields (#100). The form and the detail page both read it: the form shows the\n *  editable fields of each group under its title, the detail page every listed field or computed. */\nexport interface FieldGroup {\n  title?: Words;\n  /** Field keys, or computed keys (those show on the detail page only). */\n  fields: string[];\n  /** Start folded. The first group is never folded, whatever this says. */\n  collapsed?: boolean;\n  /** The heading folds it on the record page, remembered per device (#108). */\n  collapsible?: boolean;\n}\n\n/** An action that says what it takes (#213). A button opens a form of `input`; Ask can fill it. The\n *  values reach `run` as its third argument, checked. A bare function is an action taking nothing. */\nexport interface ActionDef {\n  run: ActionFn;\n  /** Button text; default: the key, humanised. */\n  label?: Words;\n  /** What it does, for Ask. */\n  description?: string;\n  input?: Record<string, Field>;\n}\n\n/** A computed value that says what it is called (#310). A page that shows it — a detail section, a\n *  table column — heads it with `label`; a bare function is headed by its key, humanised, in every\n *  language. */\nexport interface ComputedDef {\n  value: Computed;\n  /** What the value is called where a page shows it; default: the key, humanised. */\n  label?: Words;\n  /** Words per returned key, like an enum's `labels`. */\n  labels?: Record<string, Words>;\n  /** How an object value reads: an ICU message over its properties. */\n  format?: Words;\n}\n\nexport interface EntityDef {\n  label?: Words;\n  /** Its icon: a Lucide name (`\"dumbbell\"`). */\n  icon?: string;\n  displayField?: string;\n  fields: Record<string, Field>;\n  /** How the form and the detail page arrange the fields. Fields left out of every group follow the\n   *  last group, untitled, in declaration order. */\n  groups?: FieldGroup[];\n  /** Values worked out from the record. A function, or `{ value, label }` when a page shows it. */\n  computed?: Record<string, Computed | ComputedDef>;\n  actions?: Record<string, ActionFn | ActionDef>;\n  /** Who may change or delete a record (KA-21). `\"creator\"`: only the person who added it — anyone\n   *  else's edit does not take; `\"app\"`: only app code (docs/03). Default `\"anyone\"`. */\n  editableBy?: \"anyone\" | \"creator\" | \"app\";\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Pages & views (docs/03). Any binding, filter, or sort may be a function.\n// ─────────────────────────────────────────────────────────────────────────────\n\n/** Where tapping a row navigates. `param` maps target-param → source field key. */\n/** A tap on a row, card or pin: a page (params read off the record), or the app's own function. */\nexport type OnOpen = { page: string; param?: Record<string, string> } | ((record: Resolved, ctx: Ctx) => void | Promise<void>);\n\nexport interface ListDisplay {\n  primary?: Binding;\n  secondary?: Binding;\n  media?: string;\n  badges?: string[];\n}\n\nexport interface ListView {\n  type: \"list\";\n  entity: string;\n  filter?: FilterFn;\n  sort?: SortFn;\n  display?: ListDisplay;\n  rowActions?: string[];\n  onOpen?: OnOpen;\n  /** Shown when the page has no rows. A function of ctx may say why: `(ctx) => \\`No places in ${ctx.scope.trip?.city} yet\\``. */\n  emptyText?: Dynamic<Words>;\n  param?: string;\n  filters?: FilterChip[];\n  /** Rows under a heading per value: a field key (enum, tag, relation) or `(r) => …` (#108). */\n  group?: Binding;\n  /** Headings fold their groups, remembered per device. Needs `group`. */\n  collapsible?: boolean;\n  /** The `money` field shown per row and totalled (default: the first); `false`: none. */\n  money?: string | false;\n}\n\nexport interface GalleryView {\n  type: \"gallery\";\n  entity: string;\n  filter?: FilterFn;\n  sort?: SortFn;\n  filters?: FilterChip[];\n  display?: ListDisplay;\n  onOpen?: OnOpen;\n  emptyText?: Dynamic<Words>;\n  /** A heading per value: a field key or `(r) => …`. */\n  group?: Binding;\n  /** Headings fold their groups. */\n  collapsible?: boolean;\n  /** Words under the picture, or \"over\" it. */\n  caption?: \"below\" | \"over\";\n}\n\nexport interface TableView {\n  type: \"table\";\n  entity: string;\n  filter?: FilterFn;\n  sort?: SortFn;\n  display?: { columns: string[] };\n  /** Rows under a heading per value: a field key (enum, tag, relation) or `(r) => …` (#108). */\n  group?: Binding;\n  /** Headings fold their groups, remembered per device. Needs `group`. */\n  collapsible?: boolean;\n}\n\n/** An action reference in a detail view: an action key, or an inline navigate button. */\nexport type DetailAction =\n  | string\n  | { label: Words; navigate: { page: string; param?: Record<string, string> } };\n\nexport interface DetailSection {\n  title?: Words;\n  fields?: string[];\n  /** The heading folds it, remembered per device (#108). */\n  collapsible?: boolean;\n  /** Start folded; implies `collapsible`. */\n  collapsed?: boolean;\n}\n\nexport interface DetailView {\n  type: \"detail\";\n  entity: string;\n  param?: string;\n  /** Overrides the entity's `groups` on this page. */\n  sections?: DetailSection[];\n  actions?: DetailAction[];\n}\n\nexport interface CalendarView {\n  type: \"calendar\";\n  entity: string;\n  date: Binding;\n  title?: Binding;\n  color?: Binding;\n  filter?: FilterFn;\n}\n\n/** A filter chip surfaced in a map/list view chrome; writes into `ctx.params[param]`.\n *  - `type: \"boolean\"` → a toggle (param = true | undefined).\n *  - `type: \"geo\"` → a \"use my location\" button (param = { lat, lng } from `ctx.caps.geo`).\n *  - `type: \"text\"` → a box to type in (param = the string, undefined when empty). THIS IS SEARCH:\n *    the chip collects what was typed, the view's `filter` decides what matching means. With\n *    `filters: [{ label: \"Search\", param: \"q\", type: \"text\" }]`:\n *    `filter: (r, ctx) => !ctx.params.q || r.name.toLowerCase().includes(String(ctx.params.q).toLowerCase())`\n *  - `type: \"number\"` → the same for a figure picked at view time (\"under 30 minutes\").\n *  - `from` naming an ENTITY → record chips: one chip per record of that entity (its `displayField`),\n *    param = the selected record ids (string[]). This is how a list or map is narrowed to \"the\n *    trip / the project / the person\" chosen by the user.\n *  - otherwise `from` names an enum/tags field whose options become selectable chips (single, or\n *    multi when `multi` is set). */\nexport interface FilterChip {\n  label: Words;\n  param: string;\n  from?: string;\n  multi?: boolean;\n  type?: \"boolean\" | \"geo\" | \"text\" | \"number\";\n  /** Greyed-out hint inside a `text`/`number` box (\"Name or aisle\"). */\n  placeholder?: Words;\n}\n\n/**\n * How a map frames itself when opened. `\"remember\"` (the default) reopens where the user left it and\n * frames the markers only on a first-ever open; `\"fit\"` always frames the current markers; a literal\n * `{ center, zoom }` always opens at one fixed spot. `center` is `[lng, lat]`.\n */\nexport type MapCamera = \"remember\" | \"fit\" | { center: [number, number]; zoom: number };\n\n/**\n * A view option that may be a literal or a function of `ctx`, evaluated by the host each time the\n * view opens (and again when `ctx.scope` changes). The function form is what lets an option depend\n * on the selected record: `camera: (ctx) => ({ center: [lng, lat], zoom: 11 })` from\n * `ctx.scope.trip?.location`. Runs untrusted like `filter` does — a value in, a value out.\n */\nexport type Dynamic<T> = T | ((ctx: Ctx) => T | Promise<T>);\n\nexport interface MapView {\n  type: \"map\";\n  entity: string;\n  geo: string;\n  title?: Binding;\n  color?: Binding;\n  filter?: FilterFn;\n  filters?: FilterChip[];\n  /** Where tapping a marker goes. Without it a marker only shows its `title` in a popup. */\n  onOpen?: OnOpen;\n  camera?: Dynamic<MapCamera>;\n  /**\n   * The \"centre on me\" button, on by default where the device can answer. `false` for a map about\n   * somewhere else (a city guide, someone else's route), where it would only disappoint.\n   */\n  locate?: boolean;\n  /** The records in view as cards along the bottom (from `display`), nearest first; a pin brings its card. */\n  strip?: boolean;\n  /**\n   * What a pin's popup (or card) shows besides its title, as a list row does: a photo, a second line,\n   * tags — the photo is what says \"this is the one I meant\". The record opens OVER the map.\n   */\n  display?: ListDisplay;\n  /** A pin or strip card tapped — reach the map back with `ctx.views.map(pageId).select(id)` / `.open(id)`. */\n  onSelect?: (record: Resolved, ctx: Ctx) => void | Promise<void>;\n}\n\n/**\n * A list of things you tick (#106): groceries, packing, chores, habits. Rows in, patches out —\n * tapping a row's check flips its `done` field through `ctx.patch`, so it renders untrusted like\n * every declarative view. `steps` ticks *within* one record; this ticks *across* records.\n */\nexport interface ChecklistView {\n  type: \"checklist\";\n  entity: string;\n  /** The boolean field a tick flips — or an enum field, with `doneValue` naming the done option. */\n  done: string;\n  /** For an enum `done`: the option that means done. Un-ticking restores the enum's first other option. */\n  doneValue?: string;\n  /** The row's label. Default: the entity's display field. */\n  text?: Binding;\n  /** A quieter second line. */\n  detail?: Binding;\n  /** Rows sharing a value sit under one heading (\"Produce\", \"Dairy\"). */\n  group?: Binding;\n  filter?: FilterFn;\n  sort?: SortFn;\n  filters?: FilterChip[];\n  /** `true`: done rows disappear. `\"collapse\"`: they fold into a \"Done (n)\" section. Default: listed under \"Done\". */\n  hideDone?: boolean | \"collapse\";\n  /** The folded section's heading (\"In the basket\"). */\n  doneLabel?: Words;\n  /** false: a tick means \"have it\", not struck through. */\n  strike?: boolean;\n  /** An input at the bottom: type, Enter, next — creates a record with the text as its display field. */\n  quickAdd?: boolean | ChecklistQuickAdd;\n  rowActions?: string[];\n  /** Where the row's chevron goes. Without it a row has no detail. */\n  onOpen?: OnOpen;\n  emptyText?: Dynamic<Words>;\n}\n\nexport interface CustomView {\n  type: \"custom\";\n  entity: string;\n  param?: string;\n  /**\n   * React form: return an element. Convenient, and what most views use.\n   *\n   * Declare `mount` instead to write the view in anything else — this one names React in the app\n   * contract, which is what made the host's framework an architectural decision rather than a\n   * changeable one.\n   */\n  render?: (props: ViewProps) => ReactElement;\n  onFinish?: string;\n}\n\nexport type View =\n  | ListView\n  | GalleryView\n  | TableView\n  | DetailView\n  | CalendarView\n  | MapView\n  | StepsView\n  | ChecklistView\n  | BoardView\n  | TimelineView\n  | StatsView\n  | ChartView\n  | AggregateView\n  | CustomView;\n\nexport const VIEW_TYPES = [\n  \"list\",\n  \"gallery\",\n  \"table\",\n  \"detail\",\n  \"calendar\",\n  \"map\",\n  \"steps\",\n  \"checklist\",\n  \"board\",\n  \"timeline\",\n  \"stats\",\n  \"chart\",\n  \"aggregate\",\n  \"custom\",\n] as const;\n\nexport type ViewType = (typeof VIEW_TYPES)[number];\n\n/** One block of a page `layout` (#105): any view, with an optional title above it. */\nexport interface LayoutItem {\n  view: View;\n  title?: Words;\n  /** In a `grid`: columns out of three on a wide screen (two on a tablet, one on a phone). */\n  span?: 1 | 2 | 3;\n  /** In a `stack`: folds behind its title; the fold is remembered per device. */\n  collapsible?: boolean;\n}\n\n/**\n * Several views on one page (#105). `stack`: a column, each item under its title. `grid`: bento\n * columns by `span`, stacking on a phone. `split`: two items — a list on the left whose rows fill\n * the right item (a `detail`) instead of navigating; on a phone the rows navigate as usual.\n * `tabs`: one item at a time, chosen by a segmented control from the items' titles.\n * Every item is an ordinary view, so a layout renders for an untrusted app exactly as its views do.\n */\nexport interface PageLayout {\n  type: \"stack\" | \"grid\" | \"split\" | \"tabs\";\n  items: LayoutItem[];\n}\n\nexport const LAYOUT_TYPES = [\"stack\", \"grid\", \"split\", \"tabs\"] as const;\n\n/**\n * A button the app puts on a page, beside its filter chips.\n *\n * This is how an app adds something to TAP that is not \"open a record\" or \"make a record\". It runs\n * an ordinary function with `ctx` — no record, because a page is not a record — so it can do\n * anything `ctx` can: read the position, create something, move the map that is on screen\n * (`ctx.views`), tell the person something with `ctx.ui`.\n *\n * Unlike an action named by key (`rowActions`, a detail view's `actions`), it carries its own\n * `label`: the button says what the app wants it to say, not a prettified identifier. See\n * `CtxViews` for the one that moves a map.\n */\nexport interface PageAction {\n  label: Words;\n  /** A Lucide name, before the label. */\n  icon?: string;\n  run: (ctx: Ctx) => void | Promise<void>;\n  /** Whether it applies now, from the page's rows (\"Done shopping\" once something is ticked). */\n  when?: (rows: Resolved[], ctx: Ctx) => boolean | Promise<boolean>;\n}\n\nexport interface Page {\n  id: string;\n  /** The tab label; a function of ctx may name the selection. */\n  title: Dynamic<Words>;\n  /** A Lucide name, distinct per page; default: the entity's. */\n  icon?: string;\n  hidden?: boolean;\n  /** Figures shown above the view, computed over the page's filtered rows. */\n  summary?: SummaryValue[];\n  /** The `actions` index that adds what the page shows (the \"+\"). */\n  add?: number;\n  /** Buttons in the page's own chrome, beside its filter chips. */\n  actions?: PageAction[];\n  /** The page's view (with a `layout`: its first item's, filled in by `defineApp`). */\n  view: View;\n  /** Several views on one page (#105). A page declares EITHER `view` OR `layout`. */\n  layout?: PageLayout;\n  /** Open with no bars (a game, a slideshow). The shell keeps its own way out. */\n  fullscreen?: boolean;\n  link?: PageLink;\n}\n\n/** A page as an app declares it: `view` or `layout` (one of the two; `defineApp` fills `view` from a\n *  layout's first item). One object type rather than a union, so the functions inside a page's\n *  views keep their contextual types. */\nexport type PageInput = Omit<Page, \"view\"> & { view?: View };\n\n/** What `defineApp` accepts: pages may carry a `view` or a `layout`. */\nexport type AppInput = Omit<AppDefinition, \"pages\"> & { pages: PageInput[] };\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Reminders (docs/03)\n// ─────────────────────────────────────────────────────────────────────────────\n\nexport interface Reminder {\n  id: string;\n  entity: string;\n  when: ReminderWhen;\n  title: Binding;\n  body?: Binding;\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Migrations (docs/06) — declarative ops with a code escape hatch.\n// ─────────────────────────────────────────────────────────────────────────────\n\nexport type MigrationStep =\n  | { op: \"addField\"; entity: string; field: string; default?: unknown }\n  | { op: \"dropField\"; entity: string; field: string }\n  | { op: \"renameField\"; entity: string; from: string; to: string }\n  | { op: \"changeType\"; entity: string; field: string; to: string; via: (value: unknown) => unknown }\n  | { op: \"renameEntity\"; from: string; to: string }\n  | { op: \"setDefaultForExisting\"; entity: string; field: string; value: unknown }\n  | { op: \"addRelation\"; entity: string; field: string; to: string; many?: boolean }\n  /** A record existing ones can point at (a new `list` for old items), under a fixed `id`. */\n  | { op: \"addRecord\"; entity: string; id: string; values: Record<string, unknown> }\n  | { transform: (record: PotyroRecord, ctx: Ctx) => PotyroRecord };\n\nexport interface Migration {\n  from: string;\n  to: string;\n  steps: MigrationStep[];\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Top-level app definition\n// ─────────────────────────────────────────────────────────────────────────────\n\nexport interface Theme {\n  accent?: string;\n  /** This app's own theme; default: the device's. */\n  appearance?: \"light\" | \"dark\" | \"system\";\n}\n\n/**\n * A prominent create-flow trigger (e.g. \"Start a session\"). Declarative: the shell owns the flow —\n * pick a single required enum inline (\"menu\") or open the create form (\"form\"); \"auto\" chooses menu\n * when the entity has exactly one required enum and no other required fields, else form. When\n * `open` (default true), the new record's detail is opened after creating.\n */\nexport interface QuickAction {\n  id: string;\n  label: Words;\n  /** A Lucide name. */\n  icon?: string;\n  entity: string;\n  /** `instant` creates the record straight from field defaults + `prefill` with NO form — the point\n   *  of a quick action when every field has a default (e.g. \"Start workout\" mid-gym). */\n  mode?: \"auto\" | \"form\" | \"menu\" | \"instant\";\n  open?: boolean;\n  /** Page to land on after creating. Defaults to the entity's detail page, then its list. Use this\n   *  to jump straight into a custom view (a runner/tracker) instead of a settings screen. */\n  openPage?: string;\n  prefill?: Record<string, unknown>;\n}\n\nexport interface AppDefinition {\n  id: string;\n  name: Words;\n  /** The app's icon: a Lucide name (`\"shopping-cart\"`, as on lucide.dev), drawn in the system's\n   *  stroke; or a picture — a shipped file (`\"icon.svg\"`), an inline `<svg>`, a `data:` image. */\n  icon?: string;\n  version: string;\n  /** The DATA version: bump it only when records change shape, never for words. */\n  schemaVersion: number;\n  /** The language its words are written in, always declared (\"pl\"); every map has it. */\n  language?: Language;\n  /** Every language it carries, its own first: `[\"en\", \"pl\"]`. Added only when asked (`translate`). */\n  languages?: Language[];\n  theme?: Theme;\n  /** Live launcher tile (docs/04 §Tile). */\n  tile?: (ctx: Ctx) => TileContent | Promise<TileContent>;\n  /** Launcher group: \"games\". */\n  category?: string;\n  permissions?: PermissionManifest;\n  /** An app-wide selected record (\"current trip\") that every function can read as `ctx.scope`. */\n  scope?: ScopeDef;\n  /** How the app presents its object types: a grid home or a tab bar. Default: grid when there are\n   *  several entities, tabs when few. */\n  nav?: \"grid\" | \"tabs\";\n  /** Prominent create triggers shown in the action bar / grid home. When omitted, the shell\n   *  auto-derives an \"Add: <Entity>\" per top-level entity; `[]` says nothing is added by hand (records\n   *  the app makes itself, like a live feed's): no floating add, and a map has no place button. */\n  quickActions?: QuickAction[];\n  entities: Record<string, EntityDef>;\n  pages: Page[];\n  reminders?: Reminder[];\n  migrations?: Migration[];\n}\n\n/**\n * The result of `defineApp`. It *is* the (normalized) definition — carrying all field data\n * and live function closures — plus a brand so the host can recognize it. The host reads\n * `.definition` off a loaded module; a `PotyroApp` satisfies that by being its own definition.\n */\nexport interface PotyroApp extends AppDefinition {\n  readonly __potyroApp: true;\n}\n\n// ===== runtime.ts =====\n// App-facing runtime contracts (Runtime + ViewProps). These live in `schema` — not in the\n// runtime package — because they are part of the contract app code is typed against, and\n// keeping them here avoids a schema<->runtime type cycle. The runtime package *implements*\n// `Runtime`; view components *consume* `ViewProps`.\n\n/** Stop receiving updates. */\nexport type Unsubscribe = () => void;\n\n/** What views consume (docs/05 \"Runtime API\"). Views call this — never Store/Host/Caps. */\nexport interface Runtime {\n  /** In the language it is shown in: every `Words` slot is its string. */\n  definition: Localized<AppDefinition>;\n  language: { current: Language | undefined; default: Language | undefined; available: Language[] };\n  /** Full host surface (trust-scoped). */\n  ctx: Ctx;\n\n  // ---- data access ----\n\n  useQuery(\n    entity: string,\n    spec?: { filter?: (r: Resolved) => boolean; sort?: (a: Resolved, b: Resolved) => number },\n  ): { rows: Resolved[]; loading: boolean; error?: string };\n  useRecord(entity: string, id: Id): { record: Resolved | null; loading: boolean; error?: string };\n  runAction(entity: string, key: string, id: Id, input?: unknown): Promise<void>;\n  create(entity: string, data: Partial<PotyroRecord>): Promise<PotyroRecord>;\n  patch(entity: string, id: Id, data: Partial<PotyroRecord>): Promise<void>;\n  remove(entity: string, id: Id): Promise<void>;\n  reconcileReminders(): Promise<void>;\n}\n\n/**\n * What a custom (or built-in) view component receives (docs/05 \"View contract\"). It reaches the full\n * `ctx` via `props.runtime.ctx`.\n */\nexport interface ViewProps<Opts = unknown> {\n  runtime: Runtime;\n  entity: string;\n  /** The view's declarative bindings (functions already resolved by the runtime). */\n  options: Opts;\n  param?: Record<string, string>;\n  navigate: (pageId: string, param?: Record<string, string>) => void;\n}\n\n/** A full custom-view React component (docs/04). */\nexport type CustomViewComponent = (props: ViewProps) => ReactElement;\n";

/** Each capability's declarations (src/reference.ts `CAPABILITIES`), verbatim: read through `lookup` and `capabilityNotes`. */
export const CAPABILITY_REFERENCE: Readonly<Record<string, string>> = {
  "ctx.caps": "/**\n * Native capabilities as app code sees them. Each member is optional: for an untrusted app it\n * is `undefined` unless the permission was declared *and* granted, and when present it may be\n * a mediated (scoped/rate-limited) wrapper. Trusted apps get all of them, unmediated.\n */\nexport interface Caps {\n  camera?: CameraCapability;\n  notifications?: NotificationCapability;\n  geo?: GeoCapability;\n  haptics?: HapticsCapability;\n  filesystem?: FileCapability;\n  network?: NetworkCapability;\n  /** AI for the app's own work (docs/23). Needs `permissions: { ai: true }`. */\n  ai?: AiCapability;\n  /** Voice input, live words as the person speaks (docs/29). Needs `permissions: { speech: true }`. */\n  speech?: SpeechCapability;\n}\n\nexport interface PermissionManifest {\n  /** This app writes to a document that leaves the device (ADR D8, KA-23). The shell asks before an\n   *  app you did not write syncs; declaring it changes what that question says, not whether it is\n   *  asked. Refusing leaves the app local-only. Full rules: docs/07. */\n  sync?: boolean;\n  camera?: boolean;\n  filesystem?: boolean;\n  notifications?: boolean;\n  geo?: boolean;\n  haptics?: boolean;\n  network?: NetworkPermission;\n  /** `ctx.caps.ai` (docs/23): send what a call names to an AI service. A shared app asks the person first. */\n  ai?: boolean;\n  speech?: boolean;\n}",
  "ctx.caps.camera": "export interface CameraCapability {\n  capture(opts?: { source?: \"camera\" | \"library\" }): Promise<Blob>;\n  /** Live frames for a custom view (docs/25). Trusted apps only; one session per device; rejects with `code`. */\n  live?(opts?: LiveCameraOptions): Promise<LiveCamera>;\n}\n\nexport type LiveCameraOptions = { facing?: \"user\" | \"environment\"; width?: number; height?: number; faces?: boolean | FaceOptions };  // ideal px, 640×480\n\nexport type LiveCameraStop = \"app\" | \"person\" | \"hidden\" | \"closed\" | \"ended\" | \"replaced\";\n\nexport type LiveCameraFailure = \"denied\" | \"missing\" | \"busy\" | \"hidden\" | \"failed\";\n\n/**\n * A frame: `time` (ms, the video's clock), its size, and with `faces` the faces found and\n * `facesTime`, the `time` of the frame they were found in (`time - facesTime` is how stale they are;\n * equal with `faces: { sameFrame: true }`, which also hands `frame`, that frame's still, only valid\n * inside the callback).\n */\nexport type LiveFrameInfo = { time: number; width: number; height: number; faces?: Face[]; facesTime?: number; facesFailed?: FacesFailure; frame?: ImageBitmap };\n\n/** A running live camera. Frames are not mirrored; it stops when the page is hidden or the app is left. */\nexport interface LiveCamera {\n  readonly video: HTMLVideoElement; readonly stream: MediaStream; readonly facing: \"user\" | \"environment\";\n  readonly width: number; readonly height: number; readonly active: boolean;\n  /** What draws on this device: `\"gpu\"`, or `\"software\"` (no real graphics chip: a VM, a blocked driver) — draw less, smaller. */\n  readonly graphics: \"gpu\" | \"software\" | \"unknown\";\n  onFrame(cb: (video: HTMLVideoElement, info: LiveFrameInfo) => void): () => void;\n  snap(opts?: { type?: \"image/jpeg\" | \"image/png\" | \"image/webp\"; quality?: number }): Promise<Blob>;\n  onStop(cb: (why: LiveCameraStop) => void): () => void;\n  stop(): void;\n}",
  "Face": "/** A point in the video's pixels. */\nexport interface FacePoint {\n  x: number;\n  y: number;\n}\n\n/**\n * A point of the whole mesh (`Face.points`): `x`, `y` in the video's pixels, and `z` its depth on the\n * same scale as `x` (video pixels, approximate): 0 is about the middle of the head, NEGATIVE is\n * nearer the camera — the nose tip is the most negative. Good for which part is in front, and for\n * shading a warp; not a distance in centimetres (`Face.matrix` is that).\n */\nexport interface FaceMeshPoint extends FacePoint {\n  z: number;\n}\n\n/** One eye: its middle, the pupil (the iris's centre), its outline, and its size. */\nexport interface FaceEye {\n  center: FacePoint;\n  pupil: FacePoint;\n  /** The lids' outline, corner to corner along the top, then back along the bottom. */\n  outline: FacePoint[];\n  /** Corner to corner, in pixels. */\n  width: number;\n  /** How open it is: 0 shut, about 0.3 open (lid gap over width). */\n  open: number;\n}\n\n/** Expressions, each 0..1 (MediaPipe's blendshapes, the ones a toy needs). */\nexport interface FaceExpressions {\n  /** Lips apart (the jaw dropping, less the lips pressed). */\n  mouthOpen: number;\n  jawOpen: number;\n  smile: number;\n  /** Each eye's blink, by the person's own left and right. */\n  blinkLeft: number;\n  blinkRight: number;\n  /** Brows raised (inner and outer). */\n  browUp: number;\n  /** Brows drawn down — a frown. */\n  browDown: number;\n  /** Lips pushed forward, as for a kiss. */\n  pucker: number;\n  /** Cheeks puffed. */\n  puff: number;\n}\n\n/** A face found in a frame. */\nexport interface Face {\n  /** Around every point of the face, in video pixels. */\n  box: { x: number; y: number; w: number; h: number };\n  /** The person's own left and right eye. */\n  eyes: { left: FaceEye; right: FaceEye };\n  mouth: {\n    /** Corners: the person's left and right. */\n    left: FacePoint;\n    right: FacePoint;\n    /** The middle of the upper lip's top and of the lower lip's bottom. */\n    top: FacePoint;\n    bottom: FacePoint;\n    /** The lips' outer and inner outlines, closed loops. */\n    outer: FacePoint[];\n    inner: FacePoint[];\n  };\n  /** The tip of the nose. */\n  nose: FacePoint;\n  /** Each brow, from the nose outwards. */\n  brows: { left: FacePoint[]; right: FacePoint[] };\n  expressions: FaceExpressions;\n  /**\n   * How the head is turned, in radians: `roll` is the tilt of the eye line in the picture (positive\n   * clockwise on screen, unmirrored), `yaw` turning to the person's left is positive, `pitch` nodding\n   * down is positive.\n   */\n  turn: { roll: number; yaw: number; pitch: number };\n  /** All 478 points of the face mesh (MediaPipe's numbering), with depth, only with `faces: { points: true }`. */\n  points?: FaceMeshPoint[];\n  /**\n   * Where the head is, in 3D: MediaPipe's facial transformation matrix, 16 numbers, COLUMN-major\n   * (`m[12..14]` is the move). It takes a point of the canonical face — centimetres, the head's middle\n   * at 0, +x to the person's left, +y up, +z out of the face — to the camera's space (centimetres,\n   * the camera at 0 looking down −z, +y up). To the picture, with the camera's 63° vertical view:\n   * `const t = Math.tan((63 / 2) * Math.PI / 180), X = m[0]*x + m[4]*y + m[8]*z + m[12], Y = m[1]*x +\n   * m[5]*y + m[9]*z + m[13], Z = m[2]*x + m[6]*y + m[10]*z + m[14]; px = (1 + X / (-Z * t * width /\n   * height)) / 2 * width; py = (1 - Y / (-Z * t)) / 2 * height`. The nose tip is (0, -1.13, 7.48).\n   * Absent when the finder gives none (a fake, an older Potyro).\n   */\n  matrix?: number[];\n}\n\n/** `live({ faces })`: `true`, or options. */\nexport interface FaceOptions {\n  /** How many faces: 1–4, default 1. */\n  max?: number;\n  /** Hand over every mesh point (`Face.points`). */\n  points?: boolean;\n  /**\n   * Every frame carries the faces found in THAT frame: `onFrame` is called only once a frame's faces\n   * are found, with `info.frame`, a still of that very picture — draw it instead of the video. For a\n   * warp that must not slide off the face. Costs the find's time in lag (~20–40 ms) and frames: the\n   * rate is the finder's, not the camera's.\n   */\n  sameFrame?: boolean;\n  /**\n   * `\"high\"` finds faces in the camera's whole picture instead of one shrunk to 640 px on its long\n   * side: small or far faces are found, and their points are finer. Slower on a big picture.\n   */\n  detail?: \"normal\" | \"high\";\n}\n\n/**\n * Why a frame carries no faces although they were asked for: `\"unsupported\"` — this device or Potyro\n * cannot find faces; `\"failed\"` — finding them broke (the model would not load). The camera keeps going.\n */\nexport type FacesFailure = \"unsupported\" | \"failed\";",
  "ctx.caps.ai": "/** `ctx.caps.ai.extract`'s answer shape (docs/23): a leaf (\"number?\" may be null; a date is \"YYYY-MM-DD\"), one of a list, `[shape]`, or `{ key: shape }`. */\nexport type AiLeaf = \"text\" | \"number\" | \"boolean\" | \"date\";\n\nexport type AiShape = AiLeaf | `${AiLeaf}?` | { readonly oneOf: readonly string[]; readonly optional?: boolean } | readonly [AiShape] | { readonly [key: string]: AiShape };\n\n/** A picture: a camera Blob, bytes, a `file` field's value or a path in `ctx.files`, a `media` field's value. */\nexport type AiImage = Blob | Uint8Array | FileRef | MediaRef | string;\n\nexport interface AiExtractRequest<S extends AiShape> {\n  schema: S;\n  /** What this is and what to take from it: \"A shop receipt. One item per line bought.\" */\n  instructions?: string;\n  image?: AiImage | readonly AiImage[];\n  text?: string;\n}\n\n/**\n * AI for the app's own work (docs/23). Sends only what the call names; the answer is checked against\n * `schema` and typed from it. Needs `permissions: { ai: true }`. Throws words for the person.\n */\nexport interface AiCapability {\n  extract<const S extends AiShape>(req: AiExtractRequest<S>): Promise<AiValue<S>>;\n  ask(prompt: string, opts?: { image?: AiImage | readonly AiImage[]; instructions?: string }): Promise<string>;\n}",
  "ctx.caps.geo": "export interface GeoCapability {\n  current(): Promise<{ lat: number; lng: number }>;\n}",
  "ctx.text": "/** A `text` field with `collaborative: true`, edited as changes rather than as a whole (docs/04 \"Writing together\"). */\nexport interface CtxText {\n  /** Apply `edits`, in order, each against the text as the ones before it left it. Resolves to the record after. */\n  edit(edits: TextEdit[]): Promise<Resolved>;\n  /** The whole text as runs, each with who typed it, in order. `[]` for an empty text. */\n  runs(): Promise<TextRun[]>;\n  /**\n   * An opaque anchor that follows the character at `at` through everyone's later edits — the start\n   * of a comment's range, a bookmark. `at` equal to the length anchors the end of the text. Keep it\n   * in a text field of a record.\n   */\n  anchor(at: number): Promise<string>;\n  /** Where an anchor's character is now, or `null` once that character has been deleted. */\n  index(anchor: string): Promise<number | null>;\n}\n\n/**\n * One change to a collaborative text (`ctx.text`): put `insert` in at `at`, or take out `[from, to)`.\n * Positions count UTF-16 units of the text as this caller last read it, like `String.slice`.\n */\nexport type TextEdit = { at: number; insert: string } | { from: number; to: number };\n\n/**\n * A stretch of a collaborative text typed by one person. `by` is their account id (a `Person.id`,\n * so `ctx.people` names them), or `null` where nobody is recorded — text written before the app was\n * shared, in a store that keeps no authorship.\n */\nexport interface TextRun {\n  text: string;\n  by: string | null;\n}\n\n// Ctx, continued (ctx.text):\nexport interface Ctx {\n  /**\n   * A text several people type into at once (a `text` field with `collaborative: true`): `edit` what\n   * changed, so everyone's keystrokes merge; `runs` who typed what; an `anchor` that follows a character.\n   */\n  text(entity: string, id: Id, field: string): CtxText;\n}",
  "ctx.caps.notifications": "export interface NotificationCapability {\n  schedule(n: { id: string; at: Date; title: string; body?: string }): Promise<void>;\n  cancel(id: string): Promise<void>;\n  supportsExactScheduling: boolean;\n}",
  "ctx.caps.filesystem": "export interface FileCapability {\n  pick(): Promise<Blob>;\n  save(name: string, data: Blob): Promise<void>;\n}",
  "ctx.caps.haptics": "/** Haptic feedback (docs/04). `pattern` follows the Web Vibration API. */\nexport interface HapticsCapability {\n  vibrate(pattern?: number | number[]): Promise<void>;\n}",
  "ctx.caps.network": "export interface NetworkCapability {\n  fetch(input: string, init?: RequestInit): Promise<Response>;\n  /** A live connection to a `wss://` server (docs/28): resolves once open, rejects with a `code` (SocketFailure). */\n  socket(url: string, opts?: SocketOptions): Promise<Socket>;\n  /** Join a room on Potyro's rooms relay — a new one without `id` — for live multiplayer (docs/28). */\n  room(id?: string, opts?: RoomOptions): Promise<Room>;\n}\n\n/**\n * Network permission: on/off, or scoped to an allow-list of hosts (`\"api.example.com\"`, with\n * `\":port\"` when it is not the usual one) — for `fetch` and `socket` alike. `rooms: true` adds\n * Potyro's rooms relay (`ctx.caps.network.room`); `{ rooms: true }` alone allows nothing else.\n */\nexport type NetworkPermission = boolean | { hosts?: string[]; rooms?: boolean };",
  "ctx.caps.network.socket": "/**\n * Why `socket()` or `room()` did not connect: the `code` of the Error it rejects with, for the app to\n * word. `\"offline\"` — the device has no connection; `\"denied\"` — the person said Not now (asked again\n * next time); `\"refused\"` — the server answered no, or closed at once (browsers do not say more);\n * `\"unreachable\"` — no answer in time; `\"not-allowed-host\"` — a shared app asked for a host its\n * `permissions.network.hosts` does not name (refused without asking anyone); `\"insecure\"` — `ws://`\n * where only `wss://` can work (the web, except a local address); `\"too-many\"` — this app already\n * has 4 connections open; `\"hidden\"` — Potyro is in the background, where nothing opens (try again:\n * the first try after the person comes back opens); `\"off\"` — turned off by the person in Edit tile.\n */\nexport type SocketFailure = \"offline\" | \"denied\" | \"refused\" | \"unreachable\" | \"not-allowed-host\" | \"insecure\" | \"too-many\" | \"hidden\" | \"off\";\n\n/**\n * Why a `send` was refused: the `code` of its Error. `\"closed\"` — the connection is not open;\n * `\"too-big\"` — one message over the limit (1 MiB; a room's is 64 KiB); `\"full\"` — more than 1 MiB is\n * still waiting to go out: slow down and send again later.\n */\nexport type SocketSendFailure = \"closed\" | \"too-big\" | \"full\";\n\n/**\n * Why a connection ended. `\"app\"` — the app closed it; `\"server\"` — the server closed it (`code`,\n * `reason` say why); `\"network\"` — the connection dropped; `\"left\"` — the person left the app;\n * `\"hidden\"` — Potyro was in the background for a while (30 s, or `keepWhileHidden`); `\"too-big\"` —\n * the server sent one message over 1 MiB; `\"slow\"` — messages piled up faster than the app took them;\n * `\"stopped\"` — the shared app's box was stopped; `\"off\"` — turned off in Edit tile (do not retry).\n * Potyro never reconnects by itself: open a new one when it makes sense.\n */\nexport type SocketCloseWhy = \"app\" | \"server\" | \"network\" | \"left\" | \"hidden\" | \"too-big\" | \"slow\" | \"stopped\" | \"off\";\n\nexport interface SocketClose {\n  /** The WebSocket close code: 1000 normal, 1006 dropped without a close frame, 4000–4999 the server's own. */\n  code: number;\n  reason: string;\n  why: SocketCloseWhy;\n}\n\n/** A message: text arrives as a string, binary as bytes. */\nexport type SocketData = string | Uint8Array;\n\n/** How long a connection stays while Potyro is hidden — `\"90s\"`, `\"5m\"`; default 30 s, at most 15 min. For a chat. */\nexport type KeepWhileHidden = `${number}s` | `${number}m`;\n\n/**\n * `socket(url, opts)`: subprotocols to offer, in order. A device on the person's home network is the\n * host `local` (`ws://local:8123/…`, and `hosts: [\"local\"]` for a shared app): Potyro asks them for\n * its address once.\n */\nexport interface SocketOptions {\n  protocols?: string | string[];\n  keepWhileHidden?: KeepWhileHidden;\n}\n\n/**\n * An open connection. `socket()` resolves only once it is open, so it starts `\"open\"`. Messages that\n * arrive before `onMessage` is called are held and handed to the first callback, never lost. Inside a\n * callback `ctx` still works (`ctx.create`, `ctx.patch`…), but `ctx.now()` is the time of the call\n * that opened it: use `new Date()` for the time a message came.\n */\nexport interface Socket {\n  readonly url: string;\n  /** The subprotocol the server chose, or \"\". */\n  readonly protocol: string;\n  readonly readyState: \"open\" | \"closing\" | \"closed\";\n  /** Resolves once the message is on its way; rejects with a `code` (SocketSendFailure). */\n  send(data: SocketData): Promise<void>;\n  /** Every message, in order. Returns the unsubscribe. */\n  onMessage(cb: (data: SocketData) => void): () => void;\n  /** Once, when it ends, however it ends (called at once if it already has). Returns the unsubscribe. */\n  onClose(cb: (close: SocketClose) => void): () => void;\n  /** Close it (code 1000 unless given). `onClose` hears `why: \"app\"`. */\n  close(code?: number, reason?: string): void;\n}\n\n/** Someone in a room: `id` is new on every connection and made by the relay; `name` is what they chose. */\nexport interface RoomMember {\n  id: string;\n  name: string;\n}\n\n/** Someone came in or went. */\nexport interface RoomPresence {\n  type: \"join\" | \"leave\";\n  member: RoomMember;\n}\n\n/** `room(id, opts)`: the name the others see (display only, at most 40 characters; none by default). */\nexport interface RoomOptions {\n  name?: string;\n  keepWhileHidden?: KeepWhileHidden;\n}\n\n/**\n * A room on Potyro's rooms relay (docs/26). Anyone who has the room's `id` can join, so the id is the\n * invitation: put it in a share link (`ctx.ui.share`). `onMessage` hears the OTHER members' messages\n * exactly as they sent them (never your own); who sent one is not said — put your `me.id` in it if\n * that matters. At most 16 members, 64 KiB a message, about 30 messages a second each.\n */\nexport interface Room extends Socket {\n  /** The room's id: 22–64 characters of A–Z a–z 0–9 _ -. `room()` without one makes a new one. */\n  readonly id: string;\n  /** You in this room, as the others see you. */\n  readonly me: RoomMember;\n  /** Everyone else here now, oldest first (the first is a natural host for a game); kept current. */\n  readonly members: readonly RoomMember[];\n  /** Someone joined or left. Returns the unsubscribe. */\n  onPresence(cb: (event: RoomPresence) => void): () => void;\n}",
  "ctx.caps.speech": "/**\n * Where the words are made. `\"device\"` — on this phone or computer, nothing leaves it; `\"browser\"` —\n * the browser's own speech service (Chrome's is Google's servers); `\"cloud\"` — the recording is sent\n * to an AI service to be written down (where the browser has no speech recognition of its own).\n */\nexport type SpeechEngine = \"device\" | \"browser\" | \"cloud\";\n\n/**\n * Why `listen()` did not start, or why `result` rejected: the `code` of the Error, for the app to\n * word. `\"denied\"` — the person said Not now, or the microphone is blocked (asked again next time);\n * `\"unavailable\"` — this device has no microphone or no way to turn speech into words; `\"offline\"` —\n * the words are made online and the device is offline; `\"failed\"` — the engine stopped with an error.\n */\nexport type SpeechFailure = \"denied\" | \"unavailable\" | \"offline\" | \"failed\";\n\nexport interface SpeechOptions {\n  /** A language tag (\"pt-BR\", \"en-GB\") or a Potyro language (\"pl\"). Default: the person's, `ctx.locale`. */\n  language?: string;\n  /** Words while the person is still speaking (default true). False: only finished sentences. */\n  interim?: boolean;\n}\n\n/**\n * One listening, from the microphone turning on until `stop()`, a pause the engine takes as the end,\n * the person leaving the app, or five minutes (one minute when the words are made by an AI service).\n */\nexport interface SpeechSession {\n  /** The language tag it listens in. */\n  readonly language: string;\n  readonly engine: SpeechEngine;\n  /** False once it has ended. */\n  readonly listening: boolean;\n  /**\n   * Everything heard so far in this session (not just the newest piece), each time it changes;\n   * `final` is false while the last words may still change. Returns the unsubscribe.\n   */\n  onText(cb: (text: string, final: boolean) => void): () => void;\n  /** Stop listening: `result` then resolves with what was heard. Safe to call twice. */\n  stop(): void;\n  /** The whole text once it has ended (\"\" when nothing was said); rejects with a `code` (SpeechFailure) when the engine failed. */\n  readonly result: Promise<string>;\n}\n\n/** `ctx.caps.speech` (docs/29). Resolves once the microphone is on; one listening at a time — a new one ends the last. */\nexport interface SpeechCapability {\n  listen(opts?: SpeechOptions): Promise<SpeechSession>;\n}",
  "ctx.media": "/** Media helpers (docs/04). */\nexport interface CtxMedia {\n  put(bytes: Blob): Promise<MediaRef>;\n  url(ref: MediaRef): Promise<string>;\n}\n\n/** What a page sits on: `\"wash\"` (default, a glow of the accent), `\"dots\"`, `\"grain\"`, `\"plain\"`, or\n *  `{ image }`, a path in `ctx.files` (a shipped `\"art/kitchen.jpg\"`) shown behind the page's header\n *  and as the cover of a record page with no photo. */\nexport type Backdrop = \"plain\" | \"wash\" | \"dots\" | \"grain\" | { image: string };\n\n// Page, continued (ctx.media):\nexport interface Page {\n  /** What the page is for, in a sentence: shown where pages are listed, and under an empty page's heading. */\n  description?: Words;\n  /** The page's frequent action (\"Done shopping\"), a bottom bar: a quick action's `id` or an `actions` index. */\n  primaryAction?: string | number;\n  /** This page's ground; overrides `theme.background`. */\n  background?: Backdrop;\n}\n\n// Theme, continued (ctx.media):\nexport interface Theme {\n  /** Every page's ground; a page's own `background` wins. */\n  background?: Backdrop;\n}\n\n// DetailView, continued (ctx.media):\nexport interface DetailView {\n  /** The cover's picture: a photo field, or a computed returning a `ctx.files` path; `false`: none. */\n  media?: string | false;\n  /** Picture across the top (default), filling the screen, behind the page, a colour band, or none. */\n  cover?: \"banner\" | \"full\" | \"background\" | \"band\" | \"none\";\n  /** Fields as chips on the cover. Default: its enum fields. */\n  facts?: string[];\n  /** The ONE thing this page is for (\"Start cooking\"): a bottom bar. */\n  primaryAction?: DetailAction;\n}\n\n// ListDisplay, continued (ctx.media):\nexport interface ListDisplay {\n  /** What leads a row with no photo: a tinted initial (default), the entity's icon, or nothing. */\n  lead?: \"monogram\" | \"icon\" | \"none\";\n}\n\n// GalleryView, continued (ctx.media):\nexport interface GalleryView {\n  /** Default `\"landscape\"` (4:3). */\n  aspect?: \"square\" | \"portrait\" | \"landscape\";\n}\n\n// ActionDef, continued (ctx.media):\nexport interface ActionDef {\n  /** An icon before the label on its compact buttons: a Lucide name (`\"play\"`). */\n  icon?: string;\n}",
  "ctx.files": "/** Where a file came from: with the app, written by its code, or imported by the person (#251). */\nexport type FileOrigin = \"shipped\" | \"app\" | \"imported\";\n\n/** A file in the app's own folder (`ctx.files`). `id` never changes; `path` can (rename/move). */\nexport interface FileInfo {\n  id: string;\n  /** e.g. `notes/2026-10-11.md`, no leading slash */\n  path: string;\n  /** last segment of `path` */\n  name: string;\n  mime: string;\n  size: number;\n  hash: string;\n  origin: FileOrigin;\n  created: string;\n  updated: string;\n}\n\n/**\n * The app's own folder (#252). Name a file by path (`\"notes/a.md\"`) or by a `file` field's value.\n * Reading a missing path throws; `null` means the bytes have not reached this device yet.\n */\nexport interface CtxFiles {\n  /** All files, or those under `folder`. */\n  list(folder?: string): Promise<FileInfo[]>;\n  stat(file: string | FileRef): Promise<FileInfo | null>;\n  text(file: string | FileRef): Promise<string | null>;\n  json<T = unknown>(file: string | FileRef): Promise<T | null>;\n  bytes(file: string | FileRef): Promise<Uint8Array | null>;\n  /** For `<img>`, `<audio>`, `<video>`, a link. */\n  url(file: string | FileRef): Promise<string | null>;\n  /** Create or replace (keeps the id). */\n  write(path: string, data: string | Uint8Array | Blob, opts?: { mime?: string }): Promise<FileInfo>;\n  rename(file: string | FileRef, to: string): Promise<FileInfo>;\n  remove(file: string | FileRef): Promise<void>;\n  /** The person picks files; they land under `folder`. `[]` if they cancel. No permission needed. */\n  import(opts?: { folder?: string; accept?: string; multiple?: boolean }): Promise<FileInfo[]>;\n  /** Save a copy outside the app. */\n  export(file: string | FileRef): Promise<void>;\n}",
  "ctx.ui.share": "/** A link to the app making it: which page it opens, and with what (docs/24 §11). */\nexport interface ShareAppLink {\n  page: string;\n  params?: Record<string, string>;\n}\n\n/**\n * What a link may open a page with (docs/24 §11): the names of the `ctx.params` it takes from one —\n * `link: { params: [\"code\"] }`. A link made with `ctx.ui.share({ app: { page, params } })` opens the\n * person's copy of the app on this page; each value is text, at most `LINK_LIMITS.chars` long. A name\n * not listed here is never passed on. Without `link`, a link can open the page, with nothing.\n */\nexport interface PageLink {\n  /** The `ctx.params` a link may set on this page; anything else in a link is dropped. */\n  params?: string[];\n}\n\n/**\n * A file for `ctx.ui.share`: a picture or file the app made (a Blob — `cam.snap()`, `canvas.toBlob` — bytes, or\n * a File, which keeps its name), a file in the app's folder (a `file` field's value, a `FileInfo`), or\n * a photo field's value.\n */\nexport type ShareFile = Blob | Uint8Array | FileRef | MediaRef;\n\n// CtxUi, continued (ctx.ui.share):\nexport interface CtxUi {\n  /**\n   * Hand words, an http(s) link and/or files on: share sheet, Copy or Save a copy, after showing what\n   * goes (pictures previewed). The person picks where, so no permission. `true` when copied, shared\n   * or saved, `false` when closed. At most 10 files, 25 MB together.\n   *\n   * `app` instead of `url`: a link to THIS app, opening `page` with `params` (docs/24 §11) — on the\n   * other person's own copy when they have one, else as a demo they can keep, which then lands there.\n   * The page must declare the params (`link: { params: [...] }`); values are text. A link only opens\n   * the page: nothing runs because of it.\n   */\n  share(opts: { text?: Words; url?: string; title?: Words; app?: ShareAppLink; files?: ShareFile[] }): Promise<boolean>;\n}",
  "ctx.ui.keepAwake": "/** A screen kept on by `ui.keepAwake`. */\nexport interface UiKeepAwake {\n  /** Let the screen sleep again. Leaving the app does this too; calling it twice is fine. */\n  release(): void;\n}\n\n// CtxUi, continued (ctx.ui.keepAwake):\nexport interface CtxUi {\n  /**\n   * Keep the screen on while a page needs watching — a recipe being cooked, a workout under way —\n   * until `release()`, or until the person leaves the app. No permission: it only stops the screen\n   * dimming, and only while Potyro is in front.\n   */\n  keepAwake(): UiKeepAwake;\n}",
  "ctx.ui.timer": "/** What `ui.timer` starts: a countdown with a label. */\nexport interface UiTimerOptions {\n  /** What it is for, shown on the chip and in the notification: \"Rest\", \"Simmer the sauce\". */\n  label: Words;\n  /** How long, in seconds: 1 to 86,400 (a day). */\n  seconds: number;\n  /**\n   * Name it to have one of it: starting a timer with the id of one that is running replaces it\n   * (\"rest\" restarts the rest timer rather than adding a second). Without one, every call is new.\n   */\n  id?: string;\n}\n\n/**\n * A countdown the shell keeps (`ui.timer`). It goes on when the person changes page, leaves the app,\n * or locks the phone: a chip shows it on every page and on the home screen, and a notification rings\n * at the end (on the web, the moment Potyro is in front again when the browser could not ring).\n * The person can pause or stop it from the chip. A snapshot: read `ui.timers()` again for news.\n */\nexport interface UiTimer {\n  readonly id: string;\n  /** In the language the app is shown in. */\n  readonly label: string;\n  readonly seconds: number;\n  /** When it ends; `null` while paused. */\n  readonly endsAt: Date | null;\n  /** Seconds left when this was read (the frozen amount, while paused). */\n  readonly left: number;\n  readonly paused: boolean;\n  /**\n   * Whole seconds left now — or at `at` — rounded up, exactly as the chip counts: draw this and a\n   * countdown on the page agrees with the chip to the second. While paused, what was left.\n   */\n  secondsLeft(at?: Date | number): number;\n  cancel(): Promise<void>;\n  pause(): Promise<void>;\n  resume(): Promise<void>;\n}\n\n/** What `ui.drawsTimer` hands back. */\nexport interface UiDrawnTimer {\n  /** The page no longer draws it: its chip shows again. Leaving the page or the app does this too; twice is fine. */\n  release(): void;\n}\n\n// CtxUi, continued (ctx.ui.timer):\nexport interface CtxUi {\n  /**\n   * Start a countdown the shell keeps for the app: it survives a page change and a locked screen\n   * (see `UiTimer`). Several can run at once; at most 10 per app.\n   */\n  timer(opts: UiTimerOptions): Promise<UiTimer>;\n  /** This app's timers that are running or paused, soonest first. */\n  timers(): Promise<UiTimer[]>;\n  /**\n   * This page draws the timer `id` itself (its own countdown, on screen): until `release()`, the\n   * shell leaves out that timer's chip, so the countdown is not shown twice. Call it while the page\n   * shows the countdown — in a React effect, releasing in its cleanup. The timer still counts and\n   * rings; its chip shows on the app's other pages, when it has rung, and once the page goes.\n   */\n  drawsTimer(id: string): UiDrawnTimer;\n}",
  "ctx.guests": "/**\n * Placeholder people (`Person.guest`): name the people of a group before they join — \"Ana\", \"Tom\" —\n * so expenses, chores or turns can name them from day one. When someone joins the shared app they\n * can say which guest they are, and every record naming that guest names them from then on (no\n * record is rewritten; it reads as them). Everyone in the app sees the same guests.\n *\n * Anyone who can change the app may add one. Renaming and removing are for whoever added that guest,\n * or the app's owner; anything else throws words for the person. Works the same in a solo app (the\n * guests move with it when it is shared) and sealed.\n */\nexport interface CtxGuests {\n  /** Add a guest (a name, at most 60 characters). Store `guest.id` in a `member` field. */\n  add(name: string): Promise<Person>;\n  rename(id: Id, name: string): Promise<void>;\n  /** Take a guest off the list. Records that name it still read with its name. */\n  remove(id: Id): Promise<void>;\n}\n\n// Ctx, continued (ctx.guests):\nexport interface Ctx {\n  /**\n   * Everyone a `member` field can name right now: the space's members (just you, solo) and the\n   * guests nobody has claimed yet (`guest: true`). Use this for \"everyone in the group\" — a split,\n   * a rota — rather than `ctx.space?.members ?? [ctx.me]`, which leaves the guests out. Fixed per pass.\n   */\n  people: readonly Person[];\n  /** Add, rename and remove placeholder people (see `CtxGuests`). */\n  guests: CtxGuests;\n}",
  "ctx.space": "/** What a member may do in a space (ADR D3). */\nexport type SpaceRole = \"admin\" | \"writer\" | \"reader\";\n\nexport interface Member extends Person {\n  role: SpaceRole;\n}\n\n/**\n * The space this app's data lives in — present only when the app is synced (ADR D3).\n *\n * Absent for a solo app, which is the default. App code should read `ctx.space?.members ?? [ctx.me]`\n * rather than branching on whether sync exists: solo is \"a space with one member\", not a different\n * world.\n */\nexport interface Space {\n  id: Id;\n  members: readonly Member[];\n  /** This device's own role in the space. */\n  role: SpaceRole;\n  /**\n   * Mint an invite link. Host-mediated: the shell owns the UI and the admin check, because an app\n   * that could silently mint invites could silently hand its data to someone.\n   */\n  invite(): Promise<string>;\n}",
  "ctx.views": "/**\n * A map that is on screen right now.\n *\n * Every method answers whether it happened: `false` when that page is not the one open (its view is\n * not mounted, so there is nothing to move) — never a crash, and never silence.\n */\nexport interface MapViewControl {\n  /** Move the map. `zoom` is left alone when omitted, so this pans without throwing away the scale. */\n  flyTo(to: { center: [number, number]; zoom?: number }): Promise<boolean>;\n  /** Frame everything currently pinned — the \"show me all of it\" button. */\n  fit(): Promise<boolean>;\n  /** Bring this record's pin to the front — its card too, where the map has a strip — and the map to it. */\n  select(id: Id): Promise<boolean>;\n  /** Open this record the way a tap on its pin would: its page, over the map. */\n  open(id: Id): Promise<boolean>;\n}\n\n/**\n * Reach a view that is open and change what it is showing.\n *\n * A map opens on its `camera`, read ONCE when the view opens — the right default, and a dead end for\n * everything afterwards. This is how an app moves one later. Addressed by PAGE id and resolved when\n * called, never held. Pair it with the page's `actions` to get a button that does something:\n *\n * ```ts\n * // { id: \"map\", actions: [{ label: \"Centre on me\", run: async (ctx) => {\n * //     const here = await ctx.caps.geo!.current();\n * //     await ctx.views.map(\"map\").flyTo({ center: [here.lng, here.lat], zoom: 15 });\n * // } }], view: { type: \"map\", entity: \"place\", geo: \"where\" } }\n * ```\n */\nexport interface CtxViews {\n  map(pageId: string): MapViewControl;\n}\n\n/** Records that point at this one, as a section of its page: a plant's care log, a recipe's cooks. */\nexport interface RelatedSection {\n  entity: string;\n  /** Their relation field that points at this record. */\n  via: string;\n  /** Default `\"list\"`. `\"timeline\"` and `\"chart\"` need `date`. */\n  view?: \"list\" | \"timeline\" | \"chart\";\n  display?: ListDisplay;\n  date?: string;\n  /** Chart: the number field summed per bar; default counts. */\n  value?: string;\n  /** Chart bars; default `\"week\"`. */\n  by?: \"day\" | \"week\" | \"month\";\n  /** Newest first, at most this many (default 20). */\n  limit?: number;\n  onOpen?: OnOpen;\n}\n\n// ListDisplay, continued (ctx.views):\nexport interface ListDisplay {\n  /** An icon per record (a Lucide name, `(r) => KIND_ICON[r.kind]`): the row's lead, the map's pin. */\n  icon?: Binding;\n}\n\n// DetailSection, continued (ctx.views):\nexport interface DetailSection {\n  related?: RelatedSection;\n}",
  "ctx.format": "/** The options `ctx.format.date` takes; no others. */\nexport interface FormatDateOptions {\n  dateStyle?: \"full\" | \"long\" | \"medium\" | \"short\";\n  timeStyle?: \"short\" | \"medium\";\n  weekday?: \"long\" | \"short\";\n  day?: \"numeric\" | \"2-digit\";\n  month?: \"long\" | \"short\" | \"numeric\";\n  year?: \"numeric\" | \"2-digit\";\n  hour?: \"numeric\" | \"2-digit\";\n  minute?: \"2-digit\";\n}\n\nexport interface FormatNumberOptions {\n  style?: \"decimal\" | \"percent\" | \"unit\";\n  /** With `style: \"unit\"`: \"kilogram\", \"kilometer-per-hour\", \"day\". */\n  unit?: string;\n  minimumFractionDigits?: number;\n  maximumFractionDigits?: number;\n  signDisplay?: \"auto\" | \"always\" | \"exceptZero\";\n}\n\n/**\n * Formats for the person, the same in the sealed box. Only for text the app composes: return a Date\n * or a number where a view formats it (a `datetime` field, `AggregateRow.value`).\n */\nexport interface CtxFormat {\n  /** The tag these format in: \"pl-PL\". */\n  locale: string;\n  date(d: Date | string | number, opts?: FormatDateOptions): string;\n  number(n: number, opts?: FormatNumberOptions): string;\n  /** Whole minor units: `money(4200, \"EUR\")` → \"42,00 €\". */\n  money(minor: number, currency?: string): string;\n  /** From `ctx.now()`: \"in 3 days\". */\n  relative(d: Date | string | number, opts?: { unit?: \"minute\" | \"hour\" | \"day\" | \"week\" | \"month\" | \"year\"; numeric?: \"auto\" | \"always\" }): string;\n  list(items: string[], opts?: { type?: \"conjunction\" | \"disjunction\" }): string;\n}",
  "languages": "",
  "board": "/** Records in columns by an enum field; dragging a card, or its Move to, patches that field (#107). */\nexport interface BoardView {\n  type: \"board\";\n  entity: string;\n  /** The enum field whose options are the columns. */\n  column: string;\n  /** Which options, in order. Default: all. */\n  columns?: string[];\n  display?: ListDisplay;\n  filter?: FilterFn;\n  sort?: SortFn;\n  onOpen?: OnOpen;\n  /** `false` makes the board read-only. */\n  allowMove?: boolean;\n}",
  "timeline": "/** Records on a rail by date, newest first, under sticky day, week or month headings (#110). */\nexport interface TimelineView {\n  type: \"timeline\";\n  entity: string;\n  /** A date field, or a function returning a Date. */\n  date: Binding;\n  display?: ListDisplay;\n  /** An enum field: each dot wears its option's colour. */\n  color?: string;\n  groupBy?: \"day\" | \"week\" | \"month\";\n  newest?: \"first\" | \"last\";\n  filter?: FilterFn;\n  onOpen?: OnOpen;\n  emptyText?: Dynamic<Words>;\n}",
  "stats": "/** How a summary figure is aggregated. `count` needs no field; the rest aggregate one. */\nexport type SummaryOp = \"sum\" | \"count\" | \"avg\" | \"max\";\n\n/**\n * One figure shown above a page's view.\n *\n * Give either `op` (with a `field`, unless counting) or a `value` function — the same\n * declarative-or-function pairing as `filters`/`filter`. The declarative form is the one the\n * structural editor can edit and the one that ports to another framework, so prefer it when the\n * figure is a plain aggregate; push per-record arithmetic into a `computed` field to keep it there.\n */\nexport interface SummaryValue {\n  /** Omit when the value is its own sentence (\"You're owed €42\"). */\n  label?: Words;\n  /** The field (or computed) to aggregate. Not used with `value`, not needed for `count`. */\n  field?: string;\n  op?: SummaryOp;\n  /** Full control: receives the page's filtered, resolved rows. */\n  value?: (rows: Resolved[], ctx: Ctx) => unknown;\n}\n\n/** A stats tile (#109): a summary figure, optionally compared with the same figure for an earlier period. */\nexport interface StatItem extends SummaryValue {\n  label: Words;\n  /** After the number: \"kg\", \"min\". A `field`'s own unit is used when this is left out. */\n  unit?: Words;\n  /** `value` is the earlier figure; the tile reads \"▲ 1 more than {label}\" (or \"6% less\" with `as: \"percent\"`). */\n  compare?: { value: (rows: Resolved[], ctx: Ctx) => unknown; label: Words; as?: \"difference\" | \"percent\" };\n}\n\n/** Big numbers folded out of the page's rows (#109). */\nexport interface StatsView {\n  type: \"stats\";\n  entity: string;\n  filter?: FilterFn;\n  items: StatItem[];\n}",
  "chart": "/** One bar: its axis label, its value, and optionally the text to show for it (\"5 sessions\"). */\nexport interface ChartPoint {\n  label: string;\n  value: number;\n  text?: string;\n}\n\n/** A bar chart of the points `series` folds out of the page's rows (#109). */\nexport interface ChartView {\n  type: \"chart\";\n  entity: string;\n  filter?: FilterFn;\n  series: (rows: Resolved[], ctx: Ctx) => ChartPoint[] | Promise<ChartPoint[]>;\n  title?: Dynamic<Words>;\n  subtitle?: Dynamic<Words>;\n  emptyText?: Dynamic<Words>;\n}",
  "steps": "export interface StepsView {\n  type: \"steps\";\n  entity: string;\n  param?: string;\n  /** Field key of the ordered list to walk. */\n  list: string;\n  /** How to render one step. A field key of the list's sub-fields, or a function over the step. */\n  text?: Binding;\n  /** Action key to run once every step is ticked. Without it, finishing does nothing. */\n  onFinish?: string;\n}",
  "aggregate": "/**\n * One row of a derived table — a balance, a settle-up transfer, a remaining quantity.\n *\n * Deliberately display-ready plain data, not markup. That is the whole design of the aggregate view\n * (KA-24): the isolate bridge is a single string-in/string-out JSON function, so a *value*-returning\n * function crosses it natively, exactly as `computed`/`filter`/`summary` already do. A React\n * component would need a serializable-VDOM and event-callback protocol that does not exist — so a\n * declarative aggregate runs with the architecture's grain, and a custom view runs against it.\n */\nexport interface AggregateRow {\n  /** Stable identity for the row. Falls back to `label` when omitted. */\n  id?: string;\n  /** The row's subject — \"Ana → Bruno\", \"Milk\". */\n  label: string;\n  /** The number or amount, rendered at the end of the row. Pre-formatted if you want it exact. */\n  value?: string | number;\n  /** A quieter second line. */\n  detail?: string;\n  /**\n   * Semantic colouring — \"you are owed\" vs \"you owe\". Colour is never the only signal: the value\n   * text carries the sign too, so this stays readable in monochrome and to a screen reader.\n   */\n  tone?: \"positive\" | \"negative\" | \"neutral\";\n  /** Optional section heading; consecutive rows sharing one are grouped under it. */\n  group?: string;\n  /** Tapping the row opens this record's page. */\n  record?: { entity: string; id: string };\n  /** Tapping the row opens this page. */\n  open?: { page: string; params?: Record<string, string> };\n  /** A button on the row that runs an entity action on a record (\"Settle\", \"Water\"); `input` is what this row hands it. */\n  action?: { entity: string; id: string; key: string; label?: string; input?: Record<string, string | number | boolean> };\n}\n\n/**\n * A screen computed from the WHOLE set rather than from each record (KA-24).\n *\n * The gap this closes: `computed` is per-record and every other built-in renders rows, so \"who owes\n * whom\" and \"what's still to buy\" — the *main screen* of most shared apps — had nowhere to live but\n * a custom view. Custom views are trusted-only, so a shared app's whole point rendered blank for\n * precisely the people sharing exists to serve.\n *\n * `rows` receives the page's filtered, resolved rows and returns display-ready rows. It is ordinary\n * TypeScript — the fold, the rounding, the debt simplification — so this is not a retreat into a\n * DSL; only the *rendering* is declarative.\n */\nexport interface AggregateView {\n  type: \"aggregate\";\n  entity: string;\n  param?: string;\n  /** Fold the page's rows into what should be displayed. */\n  rows: (rows: Resolved[], ctx: Ctx) => AggregateRow[] | Promise<AggregateRow[]>;\n  /** Heading above the derived table. */\n  title?: Dynamic<Words>;\n  /** Shown when the fold returns nothing — \"Nobody owes anybody.\" */\n  emptyText?: Dynamic<Words>;\n}",
  "checklist": "/** The checklist's add box (`quickAdd: { … }`). */\nexport interface ChecklistQuickAdd {\n  /** Offer earlier items as you type. Default true. */\n  suggest?: boolean;\n  /** Fields copied from the last item with the same text (its aisle). */\n  remember?: string[];\n  /** The new item's other fields, from what was typed. */\n  defaults?: (text: string, ctx: Ctx) => Record<string, unknown> | Promise<Record<string, unknown>>;\n  /** Texts the empty box offers as one-tap chips, most likely first; ones on the list are skipped. */\n  usuals?: (rows: Resolved[], ctx: Ctx) => string[] | Promise<string[]>;\n}\n\n// ChecklistView, continued (checklist):\nexport interface ChecklistView {\n  /** Where a ticked row goes. `\"stay\"` (default) leaves it exactly where it is. `\"sink\"` moves it to\n   *  the bottom of its own group, so what is left to do stays together — at the cost of the row you\n   *  just touched leaving from under your finger. `hideDone` still wins. */\n  donePlacement?: \"sink\" | \"stay\";\n  /** An icon per item (a Lucide name), before its text. */\n  icon?: Binding;\n  /** `\"tiles\"`: items as a grid of big tappable tiles. Default `\"rows\"`. */\n  layout?: \"rows\" | \"tiles\";\n  /** Tap a row's text to rename it in place. Off by default: a row whose text is computed is not editable. */\n  editText?: boolean;\n  /** The number field holding a row's position; with it, rows can be dragged (within a group and into\n   *  another one, which sets `group`). Without it, order is `sort`'s business and rows do not drag. */\n  reorder?: string;\n  /** When `group` names a RELATION field, the groups are records: their headings can be renamed,\n   *  reordered and deleted from the list, and a new one added — `groupOrder` is the number field on\n   *  that entity holding a group's position. */\n  groupOrder?: string;\n}",
  "mount": "/** The framework-neutral form: fill `el`, return a teardown. */\nexport type CustomViewMount = (el: HTMLElement, props: ViewProps) => () => void;\n\n// CustomView, continued (mount):\nexport interface CustomView {\n  /**\n   * Framework-neutral form: put your UI inside `el`, return a teardown.\n   *\n   * ```ts\n   * mount: (el, props) => { const app = mount(Thing, { target: el, props }); return () => unmount(app); }\n   * ```\n   *\n   * The host only ever hands over a container, exactly as it does for MapLibre — so the view and the\n   * shell need not agree on a framework.\n   */\n  mount?: (el: HTMLElement, props: ViewProps) => () => void;\n}\n\n// Runtime, continued (mount):\nexport interface Runtime {\n  /**\n   * `watchQuery`/`watchRecord` are the CONTRACT: a subscription any framework can adapt. The `use*`\n   * forms below are React sugar over exactly these, kept because most views are React today — but a\n   * view written in something else is not shut out, which is what stops the view framework being an\n   * architectural decision.\n   */\n  watchQuery(\n    entity: string,\n    spec: { filter?: (r: Resolved) => boolean; sort?: (a: Resolved, b: Resolved) => number } | undefined,\n    cb: (state: { rows: Resolved[]; loading: boolean; error?: string }) => void,\n  ): Unsubscribe;\n  watchRecord(entity: string, id: Id, cb: (state: { record: Resolved | null; loading: boolean; error?: string }) => void): Unsubscribe;\n}",
  "ctx.scope": "/**\n * The one record everything else in the app belongs to — the current trip, project, season, child.\n *\n * Declaring it gives the app a header chip that shows the selected record and a picker to switch it,\n * and gives every filter, binding, computed, action and function-valued view option a synchronous\n * `ctx.scope.<entity>` to read (a `Resolved` record or `undefined`). Nothing is filtered for you:\n * a page narrows itself with `filter: (e, ctx) => e.trip?.id === ctx.scope.trip?.id`, so a page can\n * still show everything. A relation field pointing at this entity defaults to the current scope on\n * create. The selection is per device and survives reloads. Contrast `ctx.params`, which is per page.\n */\nexport interface ScopeDef {\n  /** The entity whose records are selectable. */\n  entity: string;\n  /** Chip label; defaults to the entity's label. */\n  label?: Words;\n  /** When true the app asks for a selection before showing its pages, and keeps asking until one exists. */\n  required?: boolean;\n}\n\n// Ctx, continued (ctx.scope):\nexport interface Ctx {\n  /**\n   * The app-wide selected record, when the app declares a top-level `scope` (see `ScopeDef`):\n   * `ctx.scope.trip` is the current trip as a `Resolved` record, or `undefined` while none is\n   * chosen. Synchronous and fixed per evaluation pass, so a `filter` can read it directly:\n   * `(e, ctx) => e.trip?.id === ctx.scope.trip?.id`. Always present; `{}` for an app with no scope.\n   * Per device — which trip *you* are looking at is not shared state. Live: the record as it is\n   * now — renamed, a guest added, by anyone — not as it was when picked; watchers re-run when it\n   * changes. Deleted, nothing is selected.\n   */\n  scope: Readonly<Record<string, Resolved | undefined>>;\n}",
  "sources": "/** Outside data the app's Ask can read (#213): a places API, a search engine. NEVER a key: each\n *  person brings their own, kept in the device's vault and sent only under `endpoint`. */\nexport interface SourceDef {\n  label?: string;\n  /** What it answers, for Ask. */\n  description?: string;\n  /** Base URL, https. */\n  endpoint: string;\n  /** Documentation Ask may read. */\n  docs?: string;\n  /** How the key is sent: a header (optional `prefix`, e.g. \"Bearer \"), or a query parameter. None: no key. */\n  auth?: { header: string; prefix?: string } | { query: string };\n}\n\n// AppDefinition, continued (sources):\nexport interface AppDefinition {\n  /** Outside data the app's Ask can read, by name (#213). See `SourceDef`. */\n  sources?: Record<string, SourceDef>;\n}",
  "demo": "// AppDefinition, continued (demo):\nexport interface AppDefinition {\n  /** What a demo link plays when it opens (docs/04 §Demo): a feed's replay, when sample records cannot stand in. */\n  demo?: (ctx: Ctx) => void | Promise<void>;\n}",
  "ctx.ui.form": "/** One choice in `ui.sheet` / `ui.menu`. A destructive item is shown last, in red. */\nexport interface UiItem<T = string> {\n  id: T;\n  label: Words;\n  detail?: Words;\n  /** A Lucide name. */\n  icon?: string;\n  destructive?: boolean;\n}\n\n/** A running `ui.progress` bar. */\nexport interface UiProgress {\n  /** `fraction` from 0 to 1; `detail` replaces the count on the right (\"24 of 40\"). */\n  update(fraction: number, detail?: string): void;\n  done(): void;\n}\n\n// CtxUi, continued (ctx.ui.form):\nexport interface CtxUi {\n  /** A short list of choices: a bottom sheet on a phone, a small dialog on a wide screen. Null when dismissed. */\n  sheet<T = string>(opts: { title?: Words; items: UiItem<T>[] }): Promise<T | null>;\n  /** The same, hanging under the button that ran the action on a wide screen (a sheet on a phone). */\n  menu<T = string>(opts: { title?: Words; items: UiItem<T>[] }): Promise<T | null>;\n  /** Several values at once, with the record form's controls. Relations come back as ids; null when cancelled. */\n  form<T = Record<string, unknown>>(opts: { title: Words; fields: Record<string, Field>; initial?: Partial<T>; submit?: Words }): Promise<T | null>;\n  /** A progress bar for a long action. */\n  progress(label: Words): UiProgress;\n}"
};
